import React from "react";
import { useTable, usePagination } from "react-table";
import { CSVLink } from "react-csv";

const TableWithExport = ({ data, columns }) => {
    console.log(data); // Adicione esse log para verificar os dados
  
    const {
      getTableProps,
      getTableBodyProps,
      headerGroups,
      rows,
      prepareRow,
      canPreviousPage,
      canNextPage,
      pageOptions,
      pageIndex,
      pageSize,
      gotoPage,
      nextPage,
      previousPage,
      setPageSize,
    } = useTable(
      {
        columns,
        data,
        initialState: { pageIndex: 0, pageSize: 5 },
      },
      usePagination
    );
  
    // Verificar se pageIndex e pageSize estão definidos corretamente
    const currentPageData = rows.slice(pageIndex * pageSize, (pageIndex + 1) * pageSize);
    console.log(currentPageData); // Adicione esse log para verificar os dados da página

  return (
    <div>
      <table {...getTableProps()} style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead>
          {headerGroups.map(headerGroup => (
            <tr {...headerGroup.getHeaderGroupProps()}>
              {headerGroup.headers.map(column => (
                <th {...column.getHeaderProps()} style={{ border: "1px solid black", padding: "8px" }}>
                  {column.render("Header")}
                </th>
              ))}
            </tr>
          ))}
        </thead>
        <tbody {...getTableBodyProps()}>
          {currentPageData.length > 0 ? (
            currentPageData.map(row => {
              prepareRow(row);
              return (
                <tr {...row.getRowProps()}>
                  {row.cells.map(cell => (
                    <td {...cell.getCellProps()} style={{ border: "1px solid black", padding: "8px" }}>
                      {cell.render("Cell")}
                    </td>
                  ))}
                </tr>
              );
            })
          ) : (
            <tr>
              <td colSpan={columns.length} style={{ textAlign: "center", padding: "8px" }}>
                Nenhum dado para exibir
              </td>
            </tr>
          )}
        </tbody>
      </table>

      {/* Controles de Paginação */}
      <div>
        <button onClick={() => gotoPage(0)} disabled={!canPreviousPage}>
          {"<<"}
        </button>{" "}
        <button onClick={() => previousPage()} disabled={!canPreviousPage}>
          {"<"}
        </button>{" "}
        <button onClick={() => nextPage()} disabled={!canNextPage}>
          {">"}
        </button>{" "}
        <button onClick={() => gotoPage(pageOptions.length - 1)} disabled={!canNextPage}>
          {">>"}
        </button>{" "}
        <span>
          Página {pageIndex + 1} de {pageOptions.length > 0 ? pageOptions.length : 1}
        </span>
      </div>

      {/* Opções para mudar o número de itens por página */}
      <div>
        Exibir
        <select
          value={pageSize}
          onChange={e => setPageSize(Number(e.target.value))}
          style={{ marginLeft: "8px" }}
        >
          {[5, 10, 15].map(size => (
            <option key={size} value={size}>
              {size}
            </option>
          ))}
        </select>
        itens por página
      </div>

      {/* Botão de exportação para CSV */}
      <CSVLink
        data={currentPageData.map(row => {
          prepareRow(row);
          return row.cells.reduce((acc, cell) => {
            acc[cell.column.id] = cell.value;
            return acc;
          }, {});
        })}
        filename="dados_paginados.csv"
        className="btn btn-primary"
      >
        Exportar CSV
      </CSVLink>
    </div>
  );
};

export default TableWithExport;
